#!/bin/bash
# Paste this script into CloudStack's User Data panel without manual base64 encoding.
# Replace the placeholder with a unique SHA-512 crypt hash generated by:
#   openssl passwd -6
# Never commit a populated copy of this file.

set -euo pipefail

PASSWORD_HASH='$6$REPLACE_WITH_A_UNIQUE_SHA512_CRYPT_HASH'

printf 'root:%s\n' "$PASSWORD_HASH" | chpasswd -e
unset PASSWORD_HASH

install -o root -g root -m 0600 /dev/null \
  /var/lib/cloud/root-password-from-userdata
printf '%s\n' 'Root password applied by CloudStack User Data.' \
  > /var/lib/cloud/root-password-from-userdata

# cloud-init runs scripts-user once per instance. Unlink its local script copy.
rm -f -- "$0"
